function renderRelatedProjects(current,projects=[]){
  const seen=new Set([String(current?.id||''),String(current?.slug||'')]);
  const eligible=[];
  for(const project of projects){
    if(!project||project.status!=='published'||!project.slug)continue;
    const id=String(project.id||'');const slug=String(project.slug||'');
    if(seen.has(id)||seen.has(slug))continue;
    if(eligible.some(x=>String(x.id||'')===id||String(x.slug||'')===slug))continue;
    seen.add(id);seen.add(slug);eligible.push(project);
  }
  eligible.sort((a,b)=>{
    const orderB=Number(b.sort_order||0),orderA=Number(a.sort_order||0);
    if(orderB!==orderA)return orderB-orderA;
    return String(b.updated_at||'').localeCompare(String(a.updated_at||''));
  });
  const selected=eligible.slice(0,2);
  const cards=selected.map(project=>{
    const title=String(project.title||'Untitled project');
    const category=String(project.category||'Product Design');
    const description=String(project.short_description||project.description||project.subtitle||'');
    const image=String(project.cover_image_url||project.hero_image_url||'');
    const href='/case-study.html?slug='+encodeURIComponent(project.slug);
    return '<a class="related-project-card" href="'+esc(href)+'" aria-label="View case study: '+esc(title)+'"><div class="related-project-media">'+(image?'<img loading="lazy" src="'+esc(image)+'" alt="'+esc(title)+' project preview">':'<div class="related-project-no-image" aria-hidden="true"></div>')+'<span class="related-project-arrow" aria-hidden="true">↗</span></div><div class="related-project-meta"><span>'+esc(category)+'</span><h3>'+esc(title)+'</h3><p>'+esc(description)+'</p></div></a>';
  }).join('');
  return '<section class="related-projects" aria-labelledby="relatedProjectsHeading"><div class="related-projects-heading"><span class="related-eyebrow">MORE PROJECTS</span><h2 id="relatedProjectsHeading">Explore more of my work.</h2><p>A selection of other projects exploring product design, digital experiences, and user-centered solutions.</p></div>'+(cards?'<div class="related-project-grid">'+cards+'</div>':'<p class="related-projects-empty">More case studies are coming soon.</p>')+'<a class="related-all-link" href="/#work">Explore all projects <span aria-hidden="true">↗</span></a></section>';
}
async function loadRelatedProjects(current){
  try{const response=await fetch(API+'/portfolio');if(!response.ok)throw Error('Related projects unavailable');const data=await response.json();return renderRelatedProjects(current,Array.isArray(data.projects)?data.projects:[])}
  catch(error){console.warn('Related projects could not be loaded',error);return renderRelatedProjects(current,[])}
}
